import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Program {

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        long n1 = fs.nextLong();
        long n2 = fs.nextLong();
        int n = fs.nextInt();

        int idx = (n - 1) % 6;
        boolean neg = false;
        long current = n1;

        if (idx >= 3) {
            neg = true;
            idx -= 3;
        }

        if (idx == 1) {
            current = n2;
        } else if (idx == 2) {
            current = n2 - n1;
        }

        if (neg) {
            current = -current;
        }

        long mod = 1000000007;
        System.out.println((current % mod + mod) % mod);
    }

    public static int getLastChildGoingHome(int[] inputs, int candies) {
        for (int i = 0; i < inputs.length; i++) {
            if (inputs[i] % candies == 0) {
                inputs[i] = inputs[i] / candies;
            } else {
                inputs[i] = (inputs[i] / candies) + 1;
            }
        }

        int last = 0;
        int lastIdx = 0;

        for (int i = 0; i < inputs.length; i++) {
            if (inputs[i] >= last) {
                last = inputs[i];
                lastIdx = i;
            }
        }

        return lastIdx + 1;
    }
}

